describe('validateSubclass', () => {
  afterEach(() => {
    // Clean up the WeakMap entries to avoid cross-test pollution
    // There's no direct way to clear a WeakMap, so delete known test keys.
  })

  test('returns undefined when classesData has the ErrorClass', () => {
    class MyBase extends Error {}
    class MyError extends MyBase {}

    // mark the class as known
    classesData.set(MyError, { known: true })

    expect(validateSubclass(MyError)).toBeUndefined()

    // cleanup
    classesData.delete(MyError)
  })

  test('throws an informative error when the class is not registered', () => {
    class ParentBase extends Error {}
    class ChildError extends ParentBase {}

    // ensure it's not registered
    classesData.delete(ChildError)

    try {
      validateSubclass(ChildError)
      // If no error was thrown, fail the test
      throw new Error('validateSubclass did not throw')
    } catch (err) {
      expect(err).toBeInstanceOf(Error)

      const expected = `"new ${ChildError.name}()" must not be directly called.\nThis error class should be created like this instead:\n  export const ${ChildError.name} = ${ParentBase.name}.subclass('${ChildError.name}')`
      expect(err.message).toBe(expected)
    }
  })

  test('different classes with same name are treated by identity (WeakMap)', () => {
    // Create two classes with the same name by using the class expression name property
    const Parent = class ParentName extends Error {}
    const A = class SameName extends Parent {}
    const B = class SameName extends Parent {}

    // Register only A
    classesData.set(A, { known: true })

    // A should be accepted
    expect(validateSubclass(A)).toBeUndefined()

    // B should throw because it's a distinct class object
    classesData.delete(B)
    try {
      validateSubclass(B)
      throw new Error('validateSubclass did not throw for B')
    } catch (err) {
